import itertools

def get_all_edge_sets(N, k):
    all_edge_sets = []
    for indices in itertools.combinations(range(1, N + 1), 2 * k):
        def generate_dyck(path, s_count, b_count):
            if len(path) == 2 * k:
                s_indices = []
                b_indices = []
                for i, char in enumerate(path):
                    if char == 's':
                        s_indices.append(indices[i])
                    else:
                        b_indices.append(indices[i])
                all_edge_sets.append(list(zip(s_indices, b_indices)))
                return
            if s_count < k:
                generate_dyck(path + ('s',), s_count + 1, b_count)
            if b_count < s_count:
                generate_dyck(path + ('b',), s_count, b_count + 1)
        generate_dyck((), 0, 0)
    return all_edge_sets

def get_transitive_closure(edges):
    adj = {}
    for s, b in edges:
        adj[s] = b
    connections = set()
    for s, b in edges:
        curr = s
        while curr in adj:
            next_node = adj[curr]
            connections.add((curr, next_node))
            curr = next_node
    return connections

def solve_small(N):
    for k in range(1, N + 1):
        edge_sets = get_all_edge_sets(N, k)
        closures = [get_transitive_closure(es) for es in edge_sets]
        found_disjoint = False
        for i in range(len(closures)):
            for j in range(i + 1, len(closures)):
                if closures[i].isdisjoint(closures[j]):
                    found_disjoint = True
                    break
            if found_disjoint:
                break
        if not found_disjoint:
            return k
    return None

