def find_max_k_for_N(N):
    # Find the largest k such that there exist M1, M2 (each of size k)
    # with C1 \cap C2 = empty.

    # Generate all valid M for a given k.
    def get_all_M(k):
        all_M = []
        # A merchant's items are (s_1, b_1), ..., (s_k, b_k)
        # with s_1 < ... < s_k and b_1 < ... < b_k.
        # This is equivalent to picking k s_i and k b_i.
        for s_indices in itertools.combinations(range(1, N + 1), k):
            for b_indices in itertools.combinations(range(1, N + 1), k):
                # For a fixed set of s_i and b_i, there is at most one
                # matching such that s_1 < s_2 < ... < s_k and b_1 < b_2 < ... < b_k
                # and s_i < b_i for all i.
                # The matching is: sort s_i, sort b_i, and pair them.
                # Then check if s_i < b_i.
                s_vals = sorted(list(s_indices))
                b_vals = sorted(list(b_indices))
                items = []
                valid = True
                for i in range(k):
                    if s_vals[i] >= b_vals[i]:
                        valid = False
                        break
                    items.append((s_vals[i], b_vals[i]))
                if valid:
                    all_M.append(items)
        return all_M

    for k in range(1, N):
        all_M = get_all_M(k)
        found_disjoint = False
        for i in range(len(all_M)):
            C1 = get_connections(all_M[i])
            for j in range(i, len(all_M)):
                C2 = get_connections(all_M[j])
                if C1.isdisjoint(C2):
                    found_disjoint = True
                    break
            if found_disjoint: break

        if found_disjoint:
            return k
    return 0

